import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportExportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String body = req.getReader().lines().reduce("", String::concat);

        try {
            JSONObject json = new JSONObject(body);
            String reportId = json.getString("report_id");
            String dateRange = json.optString("date_filter", "");
            String orgId = json.getString("org_id");

            // Validate report_id format (UUID)
            if (!reportId.matches("[0-9a-fA-F\\-]{36}")) {
                resp.setStatus(400);
                resp.getWriter().write("{\"error\": \"invalid report_id format\"}");
                return;
            }

            // Validate org_id is numeric
            if (!orgId.matches("\\d+")) {
                resp.setStatus(400);
                resp.getWriter().write("{\"error\": \"invalid org_id\"}");
                return;
            }

            // Build query with date filter
            String query = "SELECT r.id, r.title, r.created_at, r.payload " +
                          "FROM reports r WHERE r.org_id = " + orgId +
                          " AND r.report_id = '" + reportId + "'";

            // Apply optional date filter - user provides SQL date expression
            if (!dateRange.isEmpty()) {
                // Expected format: "created_at >= '2024-01-01' AND created_at <= '2024-12-31'"
                query += " AND " + dateRange;
            }

            log.info("Executing report export for org=" + orgId);

            Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("title", rs.getString("title"));
                row.put("created_at", rs.getString("created_at"));
                row.put("payload", rs.getString("payload"));
                results.put(row);
            }

            rs.close();
            stmt.close();
            conn.close();

            resp.setStatus(200);
            resp.getWriter().write(results.toString());

        } catch (JSONException e) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\": \"malformed JSON\"}");
        } catch (SQLException e) {
            log.warning("SQL error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\": \"query failed\"}");
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setStatus(405);
        resp.getWriter().write("{\"error\": \"use POST\"}");
    }
}
